const auxRowsCum=(sheet,yr,m)=> (AUX_DATA[sheet]||[]).map(r=>({name:r.name,monto:auxPeriodsThrough(yr,m).reduce((sum,k)=>sum+(r.values?.[k]||0),0)}));
