const gV=(d,pl,or,yr,m)=>d.filter(r=>normPL(r[0])===normPL(pl)&&r[1]===or&&r[2]===yr&&r[3]===m).reduce((s,r)=>s+r[9],0);
const gVms=(d,pl,or,yr,ms)=>ms.reduce((s,m)=>s+gV(d,pl,or,yr,m),0);
