const _fsIndexCache = new WeakMap();
function fsIndex(rows) {
  let index = _fsIndexCache.get(rows);
  if (index) return index;
  index = new Map();
  for (const row of rows) {
    const key = JSON.stringify([fsNormPL(row[0]), row[1], row[2], row[3]]);
    const acc = index.get(key) || [0, 0, 0];
    // Neumaier compensated summation; no per-row or aggregate rounding.
    const value = Number(row[9]), next = acc[0] + value;
    acc[1] += Math.abs(acc[0]) >= Math.abs(value) ? (acc[0] - next) + value : (value - next) + acc[0];
    acc[0] = next; acc[2]++; index.set(key, acc);
  }
  _fsIndexCache.set(rows, index); return index;
}
function fsGetValue(rows, pl, origin, year, month) {
  const acc = fsIndex(rows).get(JSON.stringify([fsNormPL(pl), origin, year, month]));
  return acc ? acc[0] + acc[1] : 0;
}
