  const chartData = useMemo(() => MO.map((m, i) => { const p = buildFSPL(fsFd, CUR_YEAR, i+1, cm, "consolidado"); const f = buildFSPL(fsFd, CUR_YEAR, i+1, cm, "forecast"); return { name: m, Sales: Math.round(p.ns), Presupuesto: Math.round(f.ns), EBITDA: Math.round(p.ebitda), OpEx: Math.round(p.totOpex), cur: i+1 <= cm }; }), [fsFd, cm]);
{/* */}
  // Waterfall (legacy, kept for reference)
  const OC_ALL=["Salaries & Wages","Professional Fees","Sales & Marketing","Travel & Accommodation","IT (Software-Hardware)","Office Expense","Operations","Depreciation & Amortization","Financial Expense","Financial Income","Others","Regulatory","Software & Hardware","Mobility"];
{/* */}
  // OpEx por lineas del PnL - solo Reales, drill-down por clasificacion
