  const pareto = useMemo(() => { const re = fsFd.filter(r => r[1] === "Reales" && OC_ALL.includes(fsNormPL(r[0])) && ytdM.includes(r[3])); const map = {}; re.forEach(r => { const p=String(r[8]??"").trim(); const c=String(r[7]??"").trim(); if(!p||p==="--"||p==="—"||p==="- - -"||p==="NOAP"||p==="VARIOS"||!c||c==="--"||c==="—"||c==="- - -") return; if (!map[p]) map[p] = { t: 0, items: {} }; map[p].t += r[9]; if (!map[p].items[c]) map[p].items[c] = 0; map[p].items[c] += r[9] }); const arr = Object.entries(map).map(([k, v]) => ({ partner: k, total: v.t, items: v.items })).sort((a, b) => Math.abs(b.total) - Math.abs(a.total)); const grand = arr.reduce((s, x) => s + Math.abs(x.total), 0); let cum = 0; return arr.map(x => { cum += Math.abs(x.total); return { ...x, cumPct: grand ? cum / grand : 0 } }); }, [fsFd, cm]);
  const paretoMes = useMemo(() => { const re = fsFd.filter(r => r[1] === "Reales" && OC_ALL.includes(fsNormPL(r[0])) && r[3] === cm); const map = {}; re.forEach(r => { const p=String(r[8]??"").trim(); const c=String(r[7]??"").trim(); if(!p||p==="--"||p==="—"||p==="- - -"||p==="NOAP"||p==="VARIOS"||!c||c==="--"||c==="—"||c==="- - -") return; if (!map[p]) map[p] = { t: 0, items: {} }; map[p].t += r[9]; if (!map[p].items[c]) map[p].items[c] = 0; map[p].items[c] += r[9] }); const arr = Object.entries(map).map(([k, v]) => ({ partner: k, total: v.t, items: v.items })).sort((a, b) => Math.abs(b.total) - Math.abs(a.total)); const grand = arr.reduce((s, x) => s + Math.abs(x.total), 0); let cum = 0; return arr.map(x => { cum += Math.abs(x.total); return { ...x, cumPct: grand ? cum / grand : 0 } }); }, [fsFd, cm]);
  const maxPMes = paretoMes.length ? Math.abs(paretoMes[0].total) : 1;
{/* */}
